I wrote and tested a procedure that can do this in batches.



{code:sql}DELIMITER $$

CREATE PROCEDURE UpdateTakeaway(
	BatchSize INT,
    TimeoutValue INT
)
BEGIN
	DECLARE RowsLeft INT;
	SET RowsLeft = (SELECT COUNT(*) FROM taxify_delivery_order.order WHERE taxify_delivery_order.order.type = 'takeaway');

	WHILE (RowsLeft > 0) DO
			UPDATE taxify_delivery_order.order
			SET taxify_delivery_order.order.delivery_type = 'takeaway', taxify_delivery_order.order.type = 'regular'
			WHERE taxify_delivery_order.order.type = 'takeaway'
            LIMIT BatchSize;

	        SELECT SLEEP(TimeoutValue);
			SET RowsLeft = (SELECT COUNT(*) FROM taxify_delivery_order.order WHERE taxify_delivery_order.order.type = 'takeaway');
	END WHILE;
END$$
DELIMITER ;{code}

